"""Emit the generated help and skill fragments that vow/src/skill.rs includes."""

import re

from helpgen.shards import BUNDLE_PART_TEXT_BYTES, SHARD_SOURCE_BYTES, pack, split_text

GENERATED_HEADER = (
    "// GENERATED by scripts/generate_help.py from docs/spec/. Do not edit; "
    "run the script.\n"
)
GEN_DIR = "vow/src/skill_gen"


def _rust_raw_string(text: str) -> str:
    for n in range(1, 16):
        hashes = "#" * n
        if f'"{hashes}' not in text:
            return f'r{hashes}"{text}"{hashes}'
    raise ValueError("could not find Rust raw string delimiter")


def rust_help_files(json_str: str, human_str: str) -> dict[str, str]:
    body = (
        f'fn skill_json() -> String {{\n    r##"{json_str}"##\n    .to_string()\n}}\n'
        f'\nfn skill_human() -> String {{\n    r##"{human_str}"##\n        .to_string()\n}}\n'
    )
    return {f"{GEN_DIR}/help_text.rs": GENERATED_HEADER + "\n" + body}


def _const_name(path: str) -> str:
    return "SKILL_DOC_" + re.sub(r"[^A-Za-z0-9]+", "_", path).strip("_").upper()


def _shard_files(
    prefix: str, items: list[tuple[str, str]]
) -> tuple[dict[str, str], list[str]]:
    """Pack items into numbered fragment files; return (files, fragment names)."""
    files: dict[str, str] = {}
    names: list[str] = []
    for number, shard in enumerate(pack(items, SHARD_SOURCE_BYTES), start=1):
        name = f"{prefix}_{number:02d}.rs"
        body = "\n".join(source for _, source in shard)
        files[f"{GEN_DIR}/{name}"] = GENERATED_HEADER + "\n" + body
        names.append(name)
    return files, names


def rust_skill_files(
    entrypoint_md: str, bundle_md: str, support_files: dict[str, str]
) -> dict[str, str]:
    """The skill text fragments: entrypoint, bundle parts, support documents."""
    parts = split_text(bundle_md, BUNDLE_PART_TEXT_BYTES)
    part_fns = [f"skill_bundle_part_{n:02d}" for n in range(1, len(parts) + 1)]
    bundle_items = [
        (fn, f"fn {fn}() -> &'static str {{\n    {_rust_raw_string(text)}\n}}\n")
        for fn, text in zip(part_fns, parts)
    ]
    doc_items = [
        (
            path,
            f"const {_const_name(path)}: &str = {_rust_raw_string(body)};\n",
        )
        for path, body in support_files.items()
    ]
    files, bundle_names = _shard_files("bundle", bundle_items)
    doc_files, doc_names = _shard_files("docs", doc_items)
    files.update(doc_files)

    includes = "".join(f'include!("{name}");\n' for name in bundle_names + doc_names)
    pushes = "    out.push('\\n');\n".join(
        f"    out.push_str({fn}());\n" for fn in part_fns
    )
    entries = "".join(
        f'        ("{path}", {_const_name(path)}),\n' for path in support_files
    )
    text = f"""{GENERATED_HEADER}
{includes}
fn skill_entrypoint_markdown() -> String {{
    {_rust_raw_string(entrypoint_md)}
    .to_string()
}}

fn skill_bundle_markdown() -> String {{
    let mut out = String::new();
{pushes}    out
}}

fn skill_support_files() -> &'static [(&'static str, &'static str)] {{
    &[
{entries}    ]
}}
"""
    files[f"{GEN_DIR}/skill_text.rs"] = text
    return files
